import 'package:flutter_test/flutter_test.dart'; import 'package:shared_preferences/shared_preferences.dart'; import 'package:safehelm/models/contact.dart'; import 'package:safehelm/services/storage.dart';
void main(){test('contacts survive a storage reload',()async{SharedPreferences.setMockInitialValues({});final first=await Storage.create();await first.saveContacts([const EmergencyContact(name:'Mom',phone:'+919999999999',enabled:true,priority:1)]);final second=await Storage.create();expect(second.contacts().single.name,'Mom');expect(second.contacts().single.phone,'+919999999999');});}
